import json
import math
import uuid
from urllib.request import Request, urlopen
from datetime import datetime, timezone, timedelta
from IPython.display import display, HTML

# ==========================================
# 1. ポケモン全18タイプ
# ==========================================

types = {
    "normal": ("ノーマル", "#A8A77A"),
    "fire": ("ほのお", "#EE8130"),
    "water": ("みず", "#6390F0"),
    "electric": ("でんき", "#F7D02C"),
    "grass": ("くさ", "#7AC74C"),
    "ice": ("こおり", "#96D9D6"),
    "fighting": ("かくとう", "#C22E28"),
    "poison": ("どく", "#A33EA1"),
    "ground": ("じめん", "#E2BF65"),
    "flying": ("ひこう", "#A98FF3"),
    "psychic": ("エスパー", "#F95587"),
    "bug": ("むし", "#A6B91A"),
    "rock": ("いわ", "#B6A136"),
    "ghost": ("ゴースト", "#735797"),
    "dragon": ("ドラゴン", "#6F35FC"),
    "dark": ("あく", "#705746"),
    "steel": ("はがね", "#B7B7CE"),
    "fairy": ("フェアリー", "#D685AD")
}

# ==========================================
# 2. PokéAPIからデータを取得
# ==========================================

def get_json(url):
    request = Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0",
            "Accept": "application/json"
        }
    )

    with urlopen(request, timeout=30) as response:
        return json.load(response)


chart = {}

print("PokéAPIからタイプ相性を取得しています...")

for attack in types:

    url = f"https://pokeapi.co/api/v2/type/{attack}/"
    data = get_json(url)

    relations = data["damage_relations"]

    chart[attack] = {
        defense: 1.0 for defense in types
    }

    for item in relations["double_damage_to"]:
        name = item["name"]
        if name in types:
            chart[attack][name] = 2.0

    for item in relations["half_damage_to"]:
        name = item["name"]
        if name in types:
            chart[attack][name] = 0.5

    for item in relations["no_damage_to"]:
        name = item["name"]
        if name in types:
            chart[attack][name] = 0.0

print("全18タイプのデータ取得が完了しました。")


# ==========================================
# 3. 円形グラフの位置を計算
# ==========================================

size = 1000
cx = cy = size / 2

radius = 395
node_radius = 36

names = list(types.keys())
positions = {}

for i, name in enumerate(names):

    angle = (
        -math.pi / 2
        + 2 * math.pi * i / len(names)
    )

    x = cx + radius * math.cos(angle)
    y = cy + radius * math.sin(angle)

    positions[name] = (x, y)


# ==========================================
# 4. SVGの作成
# ==========================================

uid = "pokemon_" + uuid.uuid4().hex[:10]

svg = f"""
<div id="{uid}" style="
    max-width:1050px;
    margin:auto;
    font-family:'Yu Gothic',sans-serif;
">

<h2 style="text-align:center;">
ポケモン全18タイプ相性図
</h2>

<p style="text-align:center;">
<span style="color:#e53935;">● 効果抜群（2倍）</span>　
<span style="color:#1565c0;">● いまひとつ（0.5倍）</span>　
<span style="color:#333;">● 効果なし（0倍）</span>
</p>

<svg viewBox="0 0 1000 1000"
     style="width:100%;background:#fafafa;border-radius:18px;">

<defs>

<marker id="{uid}_red"
markerWidth="7" markerHeight="7"
refX="6" refY="3" orient="auto">
<path d="M0 0 L6 3 L0 6 Z" fill="#e53935"/>
</marker>

<marker id="{uid}_blue"
markerWidth="7" markerHeight="7"
refX="6" refY="3" orient="auto">
<path d="M0 0 L6 3 L0 6 Z" fill="#1565c0"/>
</marker>

<marker id="{uid}_black"
markerWidth="7" markerHeight="7"
refX="6" refY="3" orient="auto">
<path d="M0 0 L6 3 L0 6 Z" fill="#333"/>
</marker>

</defs>

<g class="edges">
"""


# ==========================================
# 5. タイプ相性の矢印を描画
# ==========================================

for attack in names:

    for defense in names:

        value = chart[attack][defense]

        # 等倍は矢印を描かない
        if value == 1:
            continue

        x1, y1 = positions[attack]
        x2, y2 = positions[defense]

        dx = x2 - x1
        dy = y2 - y1

        distance = math.hypot(dx, dy)

        if distance == 0:
            continue

        ux = dx / distance
        uy = dy / distance

        start_x = x1 + ux * (node_radius + 5)
        start_y = y1 + uy * (node_radius + 5)

        end_x = x2 - ux * (node_radius + 10)
        end_y = y2 - uy * (node_radius + 10)

        if value == 2:
            color = "#e53935"
            marker = "red"
            width = 3

        elif value == 0.5:
            color = "#1565c0"
            marker = "blue"
            width = 2

        else:
            color = "#333333"
            marker = "black"
            width = 2

        svg += f"""
        <line
            class="edge"
            data-attack="{attack}"
            data-defense="{defense}"
            data-value="{value}"
            x1="{start_x:.2f}"
            y1="{start_y:.2f}"
            x2="{end_x:.2f}"
            y2="{end_y:.2f}"
            stroke="{color}"
            stroke-width="{width}"
            stroke-opacity="0.25"
            marker-end="url(#{uid}_{marker})"
        />
        """


svg += '</g><g class="nodes">'


# ==========================================
# 6. タイプの丸を描画
# ==========================================

for name in names:

    label, color = types[name]
    x, y = positions[name]

    svg += f"""
    <g class="type-node"
       data-type="{name}"
       style="cursor:pointer;">

        <circle
            cx="{x:.2f}"
            cy="{y:.2f}"
            r="{node_radius}"
            fill="{color}"
            stroke="#333333"
            stroke-width="2"
        />

        <text
            x="{x:.2f}"
            y="{y + 5:.2f}"
            text-anchor="middle"
            font-size="13"
            font-weight="bold"
            fill="white"
            style="pointer-events:none;"
        >{label}</text>

    </g>
    """


svg += """
</g>

<text x="500" y="485"
text-anchor="middle"
font-size="28"
font-weight="bold"
fill="#333">
ポケモン
</text>

<text x="500" y="525"
text-anchor="middle"
font-size="20"
fill="#555">
全18タイプ相性
</text>

<text x="500" y="555"
text-anchor="middle"
font-size="14"
fill="#777">
タイプをクリックして確認
</text>

</svg>

<div class="type-info"
style="
    text-align:center;
    padding:15px;
    font-size:18px;
    font-weight:bold;
">
全18タイプの相性を表示中
</div>

<div class="type-detail"
style="
    text-align:center;
    padding:10px;
    font-size:15px;
    line-height:1.8;
">
タイプを選ぶと、攻撃相性が表示されます。
</div>

</div>
"""


# ==========================================
# 7. クリック操作を追加
# ==========================================

script = """
<script>
(function(){

    const root = document.getElementById("__UID__");

    if (!root) return;

    const nodes = root.querySelectorAll(".type-node");
    const edges = root.querySelectorAll(".edge");
    const graph = root.querySelector("svg");

    const info = root.querySelector(".type-info");
    const detail = root.querySelector(".type-detail");

    const labels = __LABELS__;
    const chart = __CHART__;

    let selected = null;

    function update(type){

        selected = type;

        // タイプの表示
        nodes.forEach(node => {

            const name = node.dataset.type;

            const active = (
                !type ||
                name === type ||
                (type && chart[type][name] !== 1)
            );

            node.style.opacity = active ? "1" : "0.2";

            const circle = node.querySelector("circle");

            circle.setAttribute(
                "stroke-width",
                type && name === type ? "6" : "2"
            );

            circle.setAttribute(
                "stroke",
                type && name === type ? "#111" : "#333"
            );
        });

        // 矢印の表示
        edges.forEach(edge => {

            const active = (
                !type ||
                edge.dataset.attack === type
            );

            edge.style.opacity = active ? "1" : "0.015";

            edge.setAttribute(
                "stroke-opacity",
                type && active ? "1" : "0.25"
            );

        });

        if (!type){

            info.textContent =
                "全18タイプの相性を表示中";

            detail.textContent =
                "タイプを選ぶと、攻撃相性が表示されます。";

            return;
        }

        info.textContent =
            labels[type] + "タイプで攻撃した場合";

        const strong = [];
        const weak = [];
        const zero = [];

        Object.keys(chart[type]).forEach(defense => {

            const value = chart[type][defense];

            if(value === 2){
                strong.push(labels[defense]);
            }
            else if(value === 0.5){
                weak.push(labels[defense]);
            }
            else if(value === 0){
                zero.push(labels[defense]);
            }

        });

        detail.innerHTML =
            '<span style="color:#e53935;">' +
            '効果抜群：' +
            (strong.join("、") || "なし") +
            '</span><br>' +

            '<span style="color:#1565c0;">' +
            'いまひとつ：' +
            (weak.join("、") || "なし") +
            '</span><br>' +

            '<span style="color:#333;">' +
            '効果なし：' +
            (zero.join("、") || "なし") +
            '</span>';

    }

    // タイプをクリック
    nodes.forEach(node => {

        node.addEventListener("click", function(event){

            event.stopPropagation();

            const type = node.dataset.type;

            if(selected === type){
                update(null);
            }
            else{
                update(type);
            }

        });

    });

    // タイプ以外をクリックすると元に戻す
    graph.addEventListener("click", function(event){

        if(!event.target.closest(".type-node")){
            update(null);
        }

    });

})();
</script>
"""

script = script.replace("__UID__", uid)

script = script.replace(
    "__LABELS__",
    json.dumps(
        {k: v[0] for k, v in types.items()},
        ensure_ascii=False
    )
)

script = script.replace(
    "__CHART__",
    json.dumps(chart)
)

display(HTML(svg + script))


# ==========================================
# 8. 効果抜群ランキング
# ==========================================

print("\n【効果抜群にできるタイプ数ランキング】")

ranking = []

for attack in names:

    count = sum(
        value == 2
        for value in chart[attack].values()
    )

    ranking.append(
        (types[attack][0], count)
    )

ranking.sort(
    key=lambda item: item[1],
    reverse=True
)

for i, (name, count) in enumerate(ranking, 1):
    print(f"{i}位：{name}（{count}タイプ）")


# ==========================================
# 9. 出典と取得日
# ==========================================

jst = timezone(timedelta(hours=9))

today = datetime.now(jst).strftime(
    "%Y年%m月%d日"
)

print("\n取得日：", today)

print("出典：https://pokeapi.co/docs/v2#types")
print("API：https://pokeapi.co/api/v2/type/")

for key, r in results.items():
    print(f"【{key}】 記事名: {r['title']}")
    print(f"  説明: {r['description']}")
    if r["lat"] is None:
        print(f"  場所: {r['how']}")
    else:
        print(f"  場所: 北緯{r['lat']:.3f}、東経{r['lon']:.3f}（{r['how']}）")
    print(f"  要約の文字数: {len(r['extract'])} 字")
    print(f"  要約の最初: {r['extract'][:50]}…")
    print()

from IPython.display import HTML, display

MASK = ""  # 陸地を2度ごとの点で表した地図データ（Natural Earth 110mの陸地から作成）

TEMPLATE = r'''
(function(){
const ID="__ID__",DATA=__DATA__,MASK="__MASK__";
const root=document.getElementById(ID);
const cv=root.querySelector('canvas'),cx=cv.getContext('2d');
const msg=root.querySelector('.msg'),card=root.querySelector('.card');
const W=180,H=90,rad=Math.PI/180;
const bin=atob(MASK),land=[];
for(let j=0;j<H;j++)for(let i=0;i<W;i++){const k=j*W+i;if(bin.charCodeAt(k>>3)>>(k&7)&1)land.push([90-(j+.5)*2,-180+(i+.5)*2]);}
const unit=(la,lo)=>[Math.cos(la*rad)*Math.sin(lo*rad),Math.sin(la*rad),Math.cos(la*rad)*Math.cos(lo*rad)];
const pts=land.map(([la,lo])=>unit(la,lo));
const w=cv.width,h=cv.height,R=Math.min(w,h)*.40,X0=w/2,Y0=h/2;
let rotLon=140,rotLat=20,target=null,auto=true,hl=null,amt=0;
function proj(la,lo){const a=la*rad,b=(lo-rotLon)*rad,c=rotLat*rad;
  const x=Math.cos(a)*Math.sin(b),y=Math.sin(a),z=Math.cos(a)*Math.cos(b);
  return [x,y*Math.cos(c)-z*Math.sin(c),y*Math.sin(c)+z*Math.cos(c)];}
function draw(t){
  amt+=((hl?1:0)-amt)*.05;
  const pulse=(Math.sin(t/450)+1)/2,eb=hl&&hl.globe?amt:0;
  cx.clearRect(0,0,w,h);
  const g=cx.createRadialGradient(X0,Y0,R*.9,X0,Y0,R*(1.35+eb*.25));
  g.addColorStop(0,'rgba('+(79+eb*150|0)+','+(209+eb*30|0)+',255,'+(.16+eb*.35)+')');g.addColorStop(1,'rgba(79,209,255,0)');
  cx.fillStyle=g;cx.beginPath();cx.arc(X0,Y0,R*1.6,0,7);cx.fill();
  cx.fillStyle='#07101e';cx.beginPath();cx.arc(X0,Y0,R,0,7);cx.fill();
  for(let i=0;i<land.length;i++){
    const[p,q,z]=proj(land[i][0],land[i][1]);if(z<=0)continue;
    let a=.25+z*.6,s=2,r=120,gr=200,b=255;
    if(hl){let k;
      if(hl.globe)k=.55+.45*pulse;
      else{const d=pts[i][0]*hl.u[0]+pts[i][1]*hl.u[1]+pts[i][2]*hl.u[2];k=Math.exp(-Math.pow(Math.acos(Math.max(-1,Math.min(1,d)))/.22,2));}
      a=a*(1-.55*amt*(1-k))+k*amt*.6;s=2+k*amt*2.2;r=120+k*amt*135;gr=200+k*amt*55;b=255-k*amt*120;}
    cx.fillStyle='rgba('+(r|0)+','+(gr|0)+','+(b|0)+','+Math.min(1,a)+')';
    cx.fillRect(X0+p*R-s/2,Y0-q*R-s/2,s,s);
  }
  cx.strokeStyle='rgba('+(79+eb*150|0)+',209,255,'+(.35+eb*.5)+')';cx.lineWidth=1.2+eb*1.5;cx.beginPath();cx.arc(X0,Y0,R,0,7);cx.stroke();
  if(hl&&!hl.globe){const[p,q,z]=proj(hl.lat,hl.lon);
    if(z>0){const X=X0+p*R,Y=Y0-q*R,gr=R*.32*amt;
      const g2=cx.createRadialGradient(X,Y,0,X,Y,gr);
      g2.addColorStop(0,'rgba(255,235,170,'+(.75*amt)+')');g2.addColorStop(.4,'rgba(255,190,90,'+(.25*amt)+')');g2.addColorStop(1,'rgba(255,170,60,0)');
      cx.fillStyle=g2;cx.beginPath();cx.arc(X,Y,gr,0,7);cx.fill();
      cx.fillStyle='#fff';cx.beginPath();cx.arc(X,Y,4.5,0,7);cx.fill();
      for(let n=0;n<2;n++){const ph=((t/1400)+n*.5)%1;cx.strokeStyle='rgba(255,220,140,'+((1-ph)*.8*amt)+')';cx.lineWidth=1.5;cx.beginPath();cx.arc(X,Y,6+ph*34,0,7);cx.stroke();}}}
  if(target){let d=target.lon-rotLon;d=((d+540)%360)-180;rotLon+=d*.06;rotLat+=(target.lat-rotLat)*.06;
    if(Math.abs(d)<.05&&Math.abs(target.lat-rotLat)<.05)target=null;}
  else if(auto)rotLon+=.06;
  requestAnimationFrame(draw);
}
requestAnimationFrame(draw);
let drag=null;
cv.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];auto=false;target=null;cv.setPointerCapture(e.pointerId)});
cv.addEventListener('pointermove',e=>{if(!drag)return;rotLon-=(e.clientX-drag[0])*.3;rotLat=Math.max(-85,Math.min(85,rotLat+(e.clientY-drag[1])*.3));drag=[e.clientX,e.clientY]});
cv.addEventListener('pointerup',()=>{drag=null});
function show(key){
  const d=DATA[key];if(!d)return;
  root.querySelectorAll('button').forEach(b=>b.style.background=b.textContent===key?'#4fd1ff':'#0d1a2e');
  root.querySelectorAll('button').forEach(b=>b.style.color=b.textContent===key?'#05080f':'#dce8ff');
  if(d.lat==null){hl={globe:true};target=null;auto=true;}
  else{hl={lat:d.lat,lon:d.lon,u:unit(d.lat,d.lon)};amt=0;target={lat:d.lat,lon:d.lon};auto=false;}
  card.style.display='block';
  card.querySelector('.t').textContent=d.title;
  card.querySelector('.d').textContent=d.description||'';
  card.querySelector('.w').textContent='場所: '+d.how;
  card.querySelector('.x').textContent=d.extract||'';
  card.querySelector('a').href=d.url;
  msg.textContent=d.lat==null?'地球全体を光らせています。':d.title+' の場所へ回転しました。';
}
root.querySelectorAll('button').forEach(b=>b.onclick=()=>show(b.textContent));
})();
'''

